function validate([s, chars, vals]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's has 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's contains only lowercase letters.';
  if (typeof chars !== 'string' || chars.length < 1 || chars.length > 26) return 'chars has 1 to 26 characters.';
  if (!/^[a-z]+$/.test(chars)) return 'chars contains only lowercase letters.';
  if (new Set(chars).size !== chars.length) return 'The letters in chars are all different.';
  if (!Array.isArray(vals) || vals.length !== chars.length) return 'vals has one value per letter of chars.';
  if (vals.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value in vals is an integer from -1000 to 1000.';
  return null;
}

