function maximumCostSubstring(s, chars, vals) {
  const value = new Array(26);
  for (let letter = 0; letter < 26; letter++) {
    value[letter] = letter + 1;
  }
  for (let i = 0; i < chars.length; i++) {
    value[chars.charCodeAt(i) - 97] = vals[i];
  }
  let best = 0;
  let endingHere = 0;
  for (let i = 0; i < s.length; i++) {
    const cost = value[s.charCodeAt(i) - 97];
    endingHere = Math.max(endingHere + cost, 0);
    best = Math.max(best, endingHere);
  }
  return best;
}

