function maximumCostSubstring(s, chars, vals) {
  // Sum every substring directly, looking up each letter's value as we go.
  const valueOf = ch => {
    const at = chars.indexOf(ch);
    return at === -1 ? 'abcdefghijklmnopqrstuvwxyz'.indexOf(ch) + 1 : vals[at];
  };
  let best = 0;
  for (let start = 0; start < s.length; start++) {
    let total = 0;
    for (let end = start; end < s.length; end++) {
      total += valueOf(s[end]);
      if (total > best) best = total;
    }
  }
  return best;
}

