function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Shuffle the alphabet so chars is a random set of distinct letters.
  const letters = alphabet.split('');
  for (let i = letters.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [letters[i], letters[j]] = [letters[j], letters[i]];
  }
  if (size === 'large') {
    const count = int(1, 26);
    const chars = letters.slice(0, count).join('');
    const vals = Array.from({ length: count }, () => int(-1000, 1000));
    const n = int(8000, 10000);
    let s = '';
    for (let i = 0; i < n; i++) s += alphabet[int(0, 25)];
    return [s, chars, vals];
  }
  // Small inputs use a few letters so chars often matters.
  const pool = letters.slice(0, int(2, 5));
  const count = int(1, pool.length);
  const chars = pool.slice(0, count).join('');
  const spread = rand() < 0.5 ? 30 : 1000;
  const vals = Array.from({ length: count }, () => int(-spread, rand() < 0.3 ? spread : 0));
  const n = int(1, 9);
  let s = '';
  for (let i = 0; i < n; i++) s += pool[int(0, pool.length - 1)];
  return [s, chars, vals];
}
